-- PT102-S2-Q6. Batch 04.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch04$PT102-S2-Q6$batch04$ AND q.stimulus=$batch04$One test to determine whether a person has been infected with tuberculosis consists of injecting the person with proteins extracted from the tuberculosis bacterium. Once a person has been infected by a bacterium, the person’s immune system subsequently recognizes certain proteins present in that bacterium and attacks the bacterium. This recognition also takes place in the test and results in a skin irritation at the injection site. Hence the physicians who designed the test reasoned that anyone who reacts in this manner to an injection with the tuberculosis proteins has been infected with tuberculosis.$batch04$ AND q.prompt=$batch04$Which one of the following is an assumption on which the physicians' reasoning depends?$batch04$ AND q.correct_choice=$batch04$C$batch04$) THEN RAISE EXCEPTION 'Question changed: PT102-S2-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch04$PT102-S2-Q6$batch04$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT102-S2-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch04$PT102-S2-Q6$batch04$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch04$Conclusion$batch04$, $batch04$Anyone who gets the skin irritation from the injection has been infected with tuberculosis.$batch04$), (1, $batch04$Evidence$batch04$, $batch04$Once infected, the immune system recognizes certain proteins from the bacterium and attacks. In the test, this recognition causes the skin irritation.$batch04$), (2, $batch04$Evaluate$batch04$, $batch04$The evidence shows that infection leads to the reaction. The conclusion runs the other way: the reaction proves infection. That only works if nothing else can trigger the reaction. What if someone was infected with a *different* bacterium whose proteins also set off the irritation?$batch04$), (3, $batch04$Goal$batch04$, $batch04$A defender: nothing other than tuberculosis infection can make these proteins cause the irritation.$batch04$)) v(position,label,body) WHERE q.qid=$batch04$PT102-S2-Q6$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch04$A$batch04$, $batch04$The argument is about tuberculosis proteins. It does not need every protein in every disease-causing bacterium to be recognizable.$batch04$), ($batch04$B$batch04$, $batch04$Whether skin irritation is a symptom of the disease itself is irrelevant. The test is about a reaction to an injection.$batch04$), ($batch04$C$batch04$, $batch04$Negate it: the reaction is *not* exclusive to tuberculosis, so other bacteria can trigger it too. Then a reaction does not show tuberculosis infection, and the conclusion falls apart.$batch04$), ($batch04$D$batch04$, $batch04$If the injection itself can cause tuberculosis, that is a problem for the test, not something the physicians assume.$batch04$), ($batch04$E$batch04$, $batch04$This is about whether infected people always react. The conclusion only claims that everyone who reacts is infected.$batch04$)) v(letter,body) WHERE q.qid=$batch04$PT102-S2-Q6$batch04$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
